<script setup>
import {ref,computed,onMounted,onUnmounted,watch} from 'vue';
import {Sparkles,RefreshCw,Check,Plus,Upload,Download,ShieldCheck,Clock3,Pause,Play,ExternalLink,MessageSquare,Trash2} from 'lucide-vue-next';
const props=defineProps({mode:String,section:String,companyId:String,company:Object,user:Object,posts:Array,api:Function,headers:Function});
const emit=defineEmits(['task','compose','updated']);
const data=ref(null),settings=ref(null),control=ref(null),busy=ref(false),error=ref(''),notice=ref(''),selectedKind=ref('strategy'),request=ref(''),artifactKind=ref('all'),competitor=ref({name:'',url:''}),report=ref(null),replyEdits=ref({}),connections=ref({vk:{target:'',token:'',enabled:false,monitor:false},max:{target:'',token:'',enabled:false,monitor:false}});
const from=ref(new Date(Date.now()-30*86400000).toISOString().slice(0,10)),to=ref(new Date().toISOString().slice(0,10));
const metric=ref({post_id:'',date:new Date().toISOString().slice(0,10),views:'',reactions:'',comments:'',clicks:'',leads:'',sales:'',revenue:''});
const approvers=ref(''),admins=ref(''),newSkill=ref({id:'',name:'',instruction:''}),accountAuth=ref(null);let poll;
const canManage=computed(()=>props.user?.admin||props.company?.owner_id===props.user?.id);
const artifacts=computed(()=>(data.value?.artifacts||[]).filter(v=>v.company_id===props.companyId&&(artifactKind.value==='all'||v.kind===artifactKind.value)));
const inbox=computed(()=>(data.value?.inbox||[]).filter(v=>v.company_id===props.companyId));
const usage=computed(()=>(data.value?.usage||[]).filter(v=>v.company_id===props.companyId).sort((a,b)=>b.started_at.localeCompare(a.started_at)));
const monthUsage=computed(()=>usage.value.filter(v=>v.started_at.slice(0,7)===new Date().toISOString().slice(0,7)));
const tokenTotal=computed(()=>monthUsage.value.filter(v=>v.measured).reduce((sum,v)=>sum+v.input_tokens+v.output_tokens,0));
const unknownUsage=computed(()=>monthUsage.value.filter(v=>!v.measured).length);
const windows=computed(()=>Object.values(data.value?.control?.quota?.limits||{}).flatMap(limit=>[limit.primary,limit.secondary].filter(Boolean).map(window=>({...window,name:limit.limitName||limit.limitId}))));
const availableSkills=computed(()=>[...(data.value?.skills||[]).filter(s=>s.id!=='reply'),...(settings.value?.skills||[])]);
const num=value=>value===null||value===undefined?'—':Number(value).toLocaleString('ru-RU');
const fmt=value=>value?new Date(value).toLocaleString('ru-RU',{timeZone:'Europe/Moscow',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})+' МСК':'—';
const parseIDs=text=>{const parts=text.split(',').map(v=>v.trim()).filter(Boolean);if(parts.some(v=>!/^\d+$/.test(v)||!Number.isSafeInteger(Number(v))||Number(v)<=0))throw Error('Укажите положительные числовые Telegram ID через запятую');return [...new Set(parts.map(Number))]};
const skillName=id=>availableSkills.value.find(s=>s.id===id)?.name||id;
async function load(reset=false){
 const result=await props.api('operations');data.value=result;
 if(props.mode==='control'&&props.user?.admin)accountAuth.value=await props.api('operations/auth');
 if(reset||!settings.value){settings.value=structuredClone(result.companies[props.companyId]);approvers.value=(settings.value?.policy?.approvers||[]).join(', ');control.value=structuredClone(result.control);admins.value=(control.value.admins||[props.user.id]).join(', ');
  for(const platform of ['vk','max']){const current=settings.value?.connections?.find(c=>c.platform===platform);connections.value[platform]={target:current?.target||'',token:'',enabled:current?.enabled||false,monitor:current?.monitor||false,token_set:current?.token_set||false,verified:current?.verified||false,last_error:current?.last_error||''}}
 }
 if(props.mode==='analytics')report.value=await props.api(`operations/${props.companyId}/analytics?from=${from.value}&to=${to.value}`);
}
async function run(fn){busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function saveSettings(){await run(async()=>{settings.value.policy.approvers=parseIDs(approvers.value);await props.api(`operations/${props.companyId}/settings`,settings.value,'PUT');notice.value='Правила компании сохранены';await load(true);emit('updated')})}
async function saveControl(){await run(async()=>{await props.api('operations/control',{...control.value,admins:parseIDs(admins.value)},'PUT');notice.value='Доступы и настройки AI сохранены';await load(true);emit('updated')})}
async function refreshQuota(){await run(async()=>{await props.api('operations/quota',{});await load();notice.value='Получен свежий снимок лимитов аккаунта'})}
async function connectAccount(){await run(async()=>{accountAuth.value=await props.api('operations/auth',{action:'start'});notice.value='Вход запущен. Ссылка и одноразовый код появятся через несколько секунд';await load()})}
async function cancelAccount(){await run(async()=>{await props.api('operations/auth',{action:'cancel'});await load()})}
async function createJob(kind=selectedKind.value,brief=request.value,target=''){await run(async()=>{const job=await props.api(`operations/${props.companyId}/jobs`,{kind,request:brief,target_id:target});notice.value='Задача в очереди. Результат появится здесь и в диалоге с AI';request.value='';emit('task',job.id);await load()})}
async function approveArtifact(v){await run(async()=>{await props.api(`operations/${props.companyId}/artifacts/${v.id}`,{});await load();notice.value='Материал утверждён. Утверждённая стратегия учитывается в следующих публикациях'})}
async function addCompetitor(){await run(async()=>{await props.api(`operations/${props.companyId}/competitors`,competitor.value);competitor.value={name:'',url:''};await load(true);notice.value='Источник конкурента добавлен. Нажмите «Обновить страницу» для первого снимка'})}
async function scanCompetitor(v){await run(async()=>{await props.api(`operations/${props.companyId}/competitors/${v.id}/scan`,{});await load(true);notice.value='Снимок страницы обновлён'})}
async function removeCompetitor(v){await run(async()=>{await props.api(`operations/${props.companyId}/competitors/${v.id}`,null,'DELETE');await load(true)})}
async function saveConnection(platform){await run(async()=>{await props.api(`operations/${props.companyId}/connections/${platform}`,connections.value[platform],'PUT');await load(true);notice.value='Подключение сохранено. Проверка отправки не выполнялась'})}
async function revokeConnection(platform){await run(async()=>{await props.api(`operations/${props.companyId}/connections/${platform}`,{target:connections.value[platform].target,enabled:false,monitor:false,clear_token:true},'PUT');await load(true);notice.value='Токен удалён, подключение отключено'})}
async function saveMetric(){await run(async()=>{const value={...metric.value};for(const key of ['views','reactions','comments','clicks','leads','sales','revenue'])value[key]=value[key]===''?null:Number(value[key]);await props.api(`operations/${props.companyId}/metrics`,value);await load();notice.value='Показатели сохранены'})}
async function importCSV(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;await run(async()=>{if(file.size>2*1024*1024)throw Error('CSV должен быть до 2 МБ');const res=await fetch(`/api/operations/${props.companyId}/metrics`,{method:'POST',headers:{...props.headers(),'Content-Type':'text/csv'},body:await file.text()});const result=await res.json();if(!res.ok)throw Error(result.error);await load();notice.value=`Импортировано строк: ${result.imported}`})}
function download(name,value,type='application/json'){const url=URL.createObjectURL(new Blob([value],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csvTemplate(){download('metrics-template.csv','post_id,date,views,reactions,comments,clicks,leads,sales,revenue\n','text/csv')}
function exportArtifact(v){download(`${v.kind}-v${v.version}.txt`,v.title+'\n\n'+v.body+'\n\n'+(v.data?JSON.stringify(v.data,null,2):''),'text/plain')}
async function draftReply(v){await createJob('reply','Подготовь ответ на обращение',v.id)}
async function editReply(v){await run(async()=>{await props.api(`operations/${props.companyId}/inbox/${v.id}/edit`,{draft:replyEdits.value[v.id]??v.draft,revision:v.revision});await load();notice.value='Новая версия ответа сохранена'})}
async function sendReply(v){await run(async()=>{await props.api(`operations/${props.companyId}/inbox/${v.id}/send`,{revision:v.revision});await load();notice.value='Согласованный ответ в очереди отправки'})}
async function archiveReply(v){await run(async()=>{await props.api(`operations/${props.companyId}/inbox/${v.id}/archive`,{});await load()})}
function addSkill(){if(!newSkill.value.id||!newSkill.value.name||!newSkill.value.instruction){error.value='Заполните ID, название и инструкцию навыка';return}(settings.value.skills ||= []).push({...newSkill.value});newSkill.value={id:'',name:'',instruction:''};notice.value='Навык добавлен в форму. Сохраните правила компании'}
onMounted(async()=>{await run(()=>load(true));poll=setInterval(()=>load().catch(()=>{}),8000)});onUnmounted(()=>clearInterval(poll));watch(()=>props.companyId,()=>run(()=>load(true)));watch(()=>props.mode,()=>run(()=>load()));
</script>

<template>
<div class="operations-panel">
 <div v-if="error" class="error-banner" role="alert">{{error}}</div><div v-if="notice" class="ops-notice" role="status">{{notice}}</div>
 <div v-if="!data" class="panel">Загружаем данные…</div>
 <template v-else-if="mode==='marketing'">
  <div class="page-heading"><div><div class="eyebrow">ОТ СТРАТЕГИИ К ДЕЙСТВИЯМ</div><h1>Маркетинг<span>.</span></h1><p>Стратегия, конкуренты, темы и материалы для коротких видео.</p></div></div>
  <div class="ops-columns"><form class="panel ops-form" @submit.prevent="createJob()"><h3>Поставить задачу</h3><label>Что подготовить<select v-model="selectedKind"><option v-for="s in availableSkills" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>Цель и пожелания<textarea v-model="request" rows="5" placeholder="Например: предложи темы для сотрудников на следующую неделю"></textarea></label><p class="field-note">AI использует знания компании, сохранённую стратегию и доступные показатели. Результат сохраняется отдельным материалом.</p><button class="button primary" :disabled="busy"><Sparkles :size="16"/>Подготовить</button></form>
   <section class="panel ops-form"><h3>Конкуренты и источники</h3><p class="field-note">Наблюдение за указанной публичной страницей. Добавляйте отдельные ссылки на новости или публикации. При включённой автоматизации — обновление раз в сутки.</p><form class="ops-form" @submit.prevent="addCompetitor"><label>Название конкурента<input v-model="competitor.name" required maxlength="120"/></label><label>Публичная страница<input v-model="competitor.url" type="url" required placeholder="https://example.ru/news"/></label><button class="button secondary" :disabled="busy||!canManage"><Plus :size="15"/>Добавить конкурента</button></form>
    <article v-for="v in settings?.competitors||[]" :key="v.id" class="ops-card"><b>{{v.name}}</b><a :href="v.url" target="_blank" rel="noreferrer">{{v.url}} <ExternalLink :size="12"/></a><small>Снимок: {{fmt(v.scanned_at)}} · Изменения: {{fmt(v.changed_at)}}</small><p v-if="v.error" class="error-banner">{{v.error}}</p><div class="ops-actions"><button class="button secondary" :disabled="busy" @click="scanCompetitor(v)">Обновить страницу</button><button class="icon-button" title="Убрать конкурента" @click="removeCompetitor(v)"><Trash2 :size="15"/></button></div><details v-if="v.text"><summary>Посмотреть собранные сведения</summary><pre class="ops-text">{{v.text}}</pre></details></article>
    <button v-if="settings?.competitors?.length" class="button secondary" :disabled="busy" @click="createJob('competitor','Сравни конкурентов и предложи действия для нашей компании')">Проанализировать конкурентов</button>
   </section></div>
  <section class="panel ops-form"><div class="ops-row"><h3>Сохранённые материалы</h3><select v-model="artifactKind" aria-label="Тип сохранённых материалов"><option value="all">Все материалы</option><option v-for="s in availableSkills" :key="s.id" :value="s.id">{{s.name}}</option></select></div><div v-if="!artifacts.length" class="empty-small">Результаты AI появятся здесь. Процесс и уточнения доступны в диалоге на главном экране.</div><article v-for="v in artifacts" :key="v.id" class="ops-card"><small>{{skillName(v.kind)}} · версия {{v.version}} · {{fmt(v.created_at)}} · {{v.status==='approved'?'Утверждено':'Черновик'}}</small><h3>{{v.title}}</h3><pre class="ops-text">{{v.body}}</pre><div class="ops-actions"><button v-if="v.status!=='approved'&&canManage" class="button secondary" :disabled="busy" @click="approveArtifact(v)"><Check :size="15"/>Утвердить</button><button class="button secondary" @click="exportArtifact(v)"><Download :size="15"/>Скачать материал</button><button class="button secondary" @click="emit('task',v.task_id)">Открыть диалог</button></div><div v-if="Array.isArray(v.data?.items)&&v.data.items.length" class="ops-ideas"><article v-for="(item,i) in v.data.items" :key="i"><b>{{item.date}} {{item.title}}</b><p>{{item.hook||item.brief}}</p><button class="button secondary" @click="emit('compose',`Подготовь публикацию: ${item.title}. ${item.hook||''} ${item.brief||''}. Цель: ${item.goal||''}`)">Подготовить пост по теме</button></article></div></article></section>
 </template>
 <template v-else-if="mode==='analytics'">
  <div class="page-heading"><div><div class="eyebrow">ФАКТЫ ВМЕСТО ОЩУЩЕНИЙ</div><h1>Аналитика<span>.</span></h1><p>Результаты публикаций, заявок и продаж по фактическим данным.</p></div></div>
  <section class="panel ops-form"><div class="ops-actions"><label>Снимки с<input v-model="from" type="date"/></label><label>по<input v-model="to" type="date"/></label><button class="button secondary" :disabled="busy" @click="run(()=>load())">Показать период</button><button class="button primary" :disabled="busy" @click="createJob('report',`Подготовь отчёт по снимкам показателей с ${from} по ${to}, выводы и рекомендации`)"><Sparkles :size="15"/>Подготовить отчёт</button></div><p class="field-note">{{report?.note}}</p><h3>Работа приложения за период</h3><div class="ops-metrics"><div v-for="(label,key) in {created_posts:'Создано постов',published_posts:'Опубликовано',review_posts:'На согласовании',ai_calls:'Вызовы AI',observed_comments:'Получено обращений',sent_replies:'Отправлено ответов'}" :key="key"><small>{{label}}</small><strong>{{report?.activity?.[key]??0}}</strong></div></div><h3>Показатели аудитории</h3><div class="ops-metrics"><div v-for="(label,key) in {views:'Просмотры',reactions:'Реакции',comments:'Комментарии',clicks:'Переходы',leads:'Заявки',sales:'Продажи',revenue:'Выручка'}" :key="key"><small>{{label}}</small><strong>{{num(report?.totals?.[key])}}</strong><span>Постов с данными: {{report?.coverage?.[key]||0}}</span></div></div>
   <div class="ops-table-wrap"><table><thead><tr><th>Публикация</th><th>Формат</th><th>Просмотры</th><th>Реакции</th><th>ER</th><th>Заявки</th><th>Продажи</th></tr></thead><tbody><tr v-for="v in report?.posts||[]" :key="v.post_id"><td>{{v.title}}</td><td>{{v.format}}</td><td>{{num(v.views)}}</td><td>{{num(v.reactions)}}</td><td>{{v.engagement==null?'—':v.engagement.toFixed(1)+'%'}}</td><td>{{num(v.leads)}}</td><td>{{num(v.sales)}}</td></tr></tbody></table><p v-if="!report?.posts?.length" class="empty-small">Показателей за этот период пока нет. Загрузите CSV или добавьте снимок вручную.</p></div>
   <h3>Эффективность форматов</h3><div v-for="v in report?.formats||[]" :key="v.format" class="ops-row"><b>{{v.format}}</b><span>{{v.posts}} постов · ER {{v.engagement==null?'не измерен':v.engagement.toFixed(1)+'%'}} · полных наблюдений: {{v.complete_posts}}</span></div><p class="field-note">ER = (реакции + комментарии) / просмотры. Сравнение рассчитывается только по постам со всеми тремя показателями.</p>
  </section>
  <section class="panel ops-form"><h3>Добавить фактические данные</h3><p class="field-note">Каждая строка — накопительные показатели одного поста на дату снимка. Пустое поле означает «не измерено». Выручка — в валюте вашей отчётности; используйте одну валюту.</p><div class="ops-actions"><label class="button secondary"><Upload :size="15"/>Загрузить CSV<input type="file" accept=".csv,text/csv" hidden @change="importCSV"/></label><button class="button secondary" @click="csvTemplate">Скачать шаблон CSV</button><button class="button secondary" @click="download('analytics.json',JSON.stringify(report,null,2))">Экспорт аналитики</button></div><form class="ops-form" @submit.prevent="saveMetric"><label>Публикация<select v-model="metric.post_id" required><option value="" disabled>Выберите материал</option><option v-for="p in posts||[]" :value="p.id" :key="p.id">{{p.title}} · {{p.id}}</option></select></label><div class="ops-grid"><label>Дата снимка<input v-model="metric.date" type="date" required/></label><label v-for="(label,key) in {views:'Просмотры',reactions:'Реакции',comments:'Комментарии',clicks:'Переходы',leads:'Заявки',sales:'Продажи',revenue:'Выручка'}" :key="key">{{label}}<input v-model="metric[key]" type="number" min="0" :step="key==='revenue'?'0.01':'1'" placeholder="Не измерено"/></label></div><button class="button primary" :disabled="busy||!canManage">Сохранить показатели</button></form></section>
 </template>
 <template v-else-if="mode==='inbox'">
  <div class="page-heading"><div><div class="eyebrow">ДИАЛОГ С АУДИТОРИЕЙ</div><h1>Обращения<span>.</span></h1><p>Вопросы и комментарии, подготовка и согласование ответов.</p></div></div><section class="panel ops-form"><p class="field-note">Для Telegram укажите связанную группу обсуждения в настройках компании и добавьте туда бота. Для VK/MAX нужны токены с правами чтения комментариев. Автоответы включаются отдельным разрешением.</p><div v-if="!inbox.length" class="empty-small">Новых обращений пока нет</div><article v-for="v in inbox" :key="v.id" class="ops-card"><div class="ops-row"><b>{{v.author||'Посетитель'}}</b><small>{{(v.platform||'telegram').toUpperCase()}} · {{fmt(v.created_at)}} · {{ {new:'Новое',review:'Нужно согласование',sending:'Отправляется',sent:'Отправлено',archived:'В архиве',uncertain:'Проверьте отправку'}[v.status]||v.status }}</small></div><pre class="ops-text">{{v.text}}</pre><textarea v-if="v.draft" :value="replyEdits[v.id]??v.draft" @input="replyEdits[v.id]=$event.target.value" rows="4" :disabled="['sent','sending','uncertain'].includes(v.status)" aria-label="Текст ответа"></textarea><p v-if="v.error" class="error-banner">{{v.error}}</p><div class="ops-actions"><button v-if="!['sent','sending','uncertain'].includes(v.status)" class="button secondary" :disabled="busy" @click="draftReply(v)"><Sparkles :size="15"/>Подготовить ответ</button><button v-if="v.draft&&replyEdits[v.id]!=null&&replyEdits[v.id]!==v.draft" class="button secondary" :disabled="busy" @click="editReply(v)">Сохранить правки</button><button v-if="v.draft&&v.status==='review'&&(replyEdits[v.id]==null||replyEdits[v.id]===v.draft)" class="button primary" :disabled="busy" @click="sendReply(v)">Одобрить и отправить</button><button v-if="v.status!=='sending'&&v.status!=='archived'" class="button secondary" @click="archiveReply(v)">В архив</button></div></article></section>
 </template>
 <template v-else-if="mode==='control'">
  <div class="page-heading"><div><div class="eyebrow">ПОТРЕБЛЕНИЕ И ПОЛНОМОЧИЯ</div><h1>Лимиты и доступы<span>.</span></h1><p>Расход подписки и вызовы AI, учтённые нашим приложением.</p></div></div>
  <section v-if="user?.admin" class="panel ops-form"><div class="ops-row"><h3>Подписка аккаунта</h3><button class="button secondary" :disabled="busy" @click="refreshQuota"><RefreshCw :size="15"/>Обновить лимиты</button></div><p class="field-note">Это общий расход аккаунта, включая другие приложения и чаты. Проценты подписки нельзя точно распределить по компаниям по числу токенов.</p><p v-if="!windows.length">Снимок лимитов ещё не получен. Нажмите «Обновить лимиты».</p><article v-for="(v,i) in windows" :key="i" class="ops-quota"><div class="ops-row"><b>{{v.windowDurationMins>=10080?'Недельный лимит':v.windowDurationMins>=1440?'Лимит за '+Math.round(v.windowDurationMins/1440)+' дн.':'Лимит за '+Math.round(v.windowDurationMins/60)+' ч.'}}</b><strong>{{v.usedPercent}}% использовано</strong></div><meter min="0" max="100" :value="v.usedPercent"></meter><small>Обновление: {{fmt(data.control.quota.at)}} · Сброс: {{fmt(v.resetsAt*1000)}}</small></article><p v-if="data.control.quota?.error" class="error-banner">{{data.control.quota.error}}. Показан последний сохранённый снимок.</p></section>
  <section class="panel ops-form"><h3>Эта компания · текущий месяц (UTC)</h3><div class="ops-metrics"><div><small>AI-вызовы</small><strong>{{monthUsage.length}}</strong></div><div><small>Изображения</small><strong>{{monthUsage.filter(v=>v.kind==='image').length}}</strong></div><div><small>Измеренные токены</small><strong>{{num(tokenTotal)}}</strong></div><div><small>Без статистики токенов</small><strong>{{unknownUsage}}</strong></div></div><p class="field-note">Учёт начался после включения этого раздела; неуспешные попытки тоже учитываются. Предыдущие генерации не восстановлены. Входные токены уже включают кэшированные; повторно они не прибавляются. Если вызов не вернул статистику, его расход токенов неизвестен. Отдельный расход кредитов image generation через эту статистику не измеряется.</p><div class="ops-table-wrap"><table><thead><tr><th>Когда</th><th>Операция</th><th>Вход / выход</th><th>Статус</th></tr></thead><tbody><tr v-for="v in usage.slice(0,80)" :key="v.id"><td>{{fmt(v.started_at)}}</td><td>{{v.kind==='image'?'Изображение':'Текст'}} · {{v.provider}}</td><td>{{v.measured?`${num(v.input_tokens)} / ${num(v.output_tokens)}`:'Нет статистики'}}</td><td>{{ {running:'Выполняется',completed:'Завершено',failed:'Ошибка',interrupted:'Прервано'}[v.status]||v.status }}</td></tr></tbody></table></div><button class="button secondary" @click="download('ai-usage.json',JSON.stringify(usage,null,2))">Экспорт журнала</button></section>
  <section v-if="user?.admin" class="panel ops-form"><h3>Подключение аккаунта ChatGPT</h3><p class="field-note">Существующая авторизация используется автоматически. Новый вход сохраняется в отдельном профиле приложения и не меняет вход в Codex на вашем компьютере. Пароль вводится только на странице OpenAI.</p><div v-if="accountAuth?.state==='waiting'" class="ops-card"><a v-if="accountAuth.url" :href="accountAuth.url" target="_blank" rel="noreferrer">Открыть вход в OpenAI <ExternalLink :size="14"/></a><strong v-if="accountAuth.code">Код: {{accountAuth.code}}</strong><span v-else>Получаем ссылку и одноразовый код…</span><small>Ожидание до {{fmt(accountAuth.expires_at)}}</small><button class="button secondary" @click="cancelAccount">Отменить вход</button></div><p v-else-if="accountAuth?.state==='connected'" class="ops-notice">Новый аккаунт подключён. Обновите лимиты, чтобы проверить доступ.</p><button v-if="accountAuth?.state!=='waiting'" class="button secondary" :disabled="busy" @click="connectAccount">Подключить или сменить аккаунт</button><p class="field-note">Чтобы отозвать использование аккаунта этим приложением, включите паузу всех AI-вызовов ниже. Пароли и токены в интерфейсе не показываются.</p></section>
  <form v-if="user?.admin&&control" class="panel ops-form" @submit.prevent="saveControl"><h3>Настройки AI и администраторов</h3><label class="ops-check"><input v-model="control.ai_paused" type="checkbox"/>Приостановить новые AI-вызовы для всех компаний</label><label>Остановить новые вызовы при расходе подписки, %<input v-model.number="control.stop_at_percent" type="number" min="0" max="100" step="1"/></label><p class="field-note">0 — порог выключен. Проверяется свежий снимок перед каждым вызовом; уже начавшийся вызов может перейти порог.</p><label>Исполнитель текста<select v-model="control.provider"><option value="">Codex · аккаунт ChatGPT</option><option value="codex">Codex · аккаунт ChatGPT</option><option value="ollama">Локальная модель Ollama</option></select></label><label>Модель<input v-model="control.model" placeholder="По умолчанию исполнителя" maxlength="100"/></label><p class="field-note">Для Ollama нужен работающий локальный сервис и установленная модель. Изображения по-прежнему создаются через подключённый Codex. Смена исполнителя сохраняет данные компаний.</p><label>Администраторы · Telegram ID через запятую<input v-model="admins" required/></label><p class="field-note">Удалённый из списка администратор теряет системные права. Доступ к конкретной компании регулируется её участниками.</p><button class="button primary" :disabled="busy"><ShieldCheck :size="15"/>Сохранить доступы и AI</button></form>
  <section v-if="user?.admin" class="panel ops-form"><details><summary>Журнал действий и доступов</summary><article v-for="v in (data.audit||[]).filter(v=>!v.company_id||v.company_id===companyId)" :key="v.id" class="ops-card"><small>{{fmt(v.at)}} · {{v.kind}}</small><p>{{v.text}}</p></article></details></section>
 </template>
 <template v-else-if="mode==='settings'&&settings">
  <form v-if="section!=='connections'" class="panel ops-form" @submit.prevent="saveSettings"><h3>Правила согласования публикаций</h3><label>Ответственные · Telegram ID через запятую<input v-model="approvers" placeholder="Пусто — участники компании"/></label><label>Необходимое число одобрений<input v-model.number="settings.policy.required" type="number" min="1" max="10" required/></label><label class="ops-check"><input v-model="settings.policy.separate_author" type="checkbox"/>Автор задачи не может согласовывать собственный материал</label><label class="ops-check"><input v-model="settings.policy.confirm_checks" type="checkbox"/>Перед согласованием обязательно подтвердить проверку фактов и визуала</label><p class="field-note">Ответственные должны иметь доступ к компании. Изменение правил отменяет прежние одобрения готовых материалов.</p>
   <h3>Лимиты компании</h3><label class="ops-check"><input v-model="settings.usage.paused" type="checkbox"/>Приостановить новые AI-вызовы этой компании</label><div class="ops-grid"><label>Вызовов AI в месяц<input v-model.number="settings.usage.monthly_calls" type="number" min="0"/></label><label>Изображений в месяц<input v-model.number="settings.usage.monthly_images" type="number" min="0"/></label><label>Порог учтённых токенов за месяц<input v-model.number="settings.usage.monthly_tokens" type="number" min="0"/></label><label>Порог общего расхода подписки, %<input v-model.number="settings.usage.stop_at_percent" type="number" min="0" max="100"/></label></div><p class="field-note">0 — без ограничения. Порог токенов проверяется по накопленной статистике перед вызовом и не задаёт жёсткий предел ответа модели. При неизвестном расходе следующие вызовы блокируются до изменения ограничения. Вызовы без статистики остаются отдельно в журнале.</p>
   <h3>Автономный маркетинг</h3><label class="ops-check"><input v-model="settings.automation.enabled" type="checkbox"/>Включить автономную подготовку материалов и наблюдение за конкурентами</label><label class="ops-check"><input v-model="settings.automation.topics_daily" type="checkbox"/>Ежедневно предлагать темы</label><label class="ops-check"><input v-model="settings.automation.strategy_weekly" type="checkbox"/>Раз в неделю актуализировать стратегию</label><label class="ops-check"><input v-model="settings.automation.reports_weekly" type="checkbox"/>Раз в неделю готовить отчёт с выводами и рекомендациями</label><p class="field-note">Публикации продолжают требовать отдельного согласования. Подготовленные материалы доступны в разделе «Маркетинг».</p>
   <h3>Обращения и разрешения</h3><label>ID группы обсуждения Telegram<input v-model.number="settings.discussion_chat_id" type="number" placeholder="-100…"/></label><p class="field-note">Группа должна быть связана с каналом компании. Добавьте в неё бота и разрешите ему получать сообщения.</p><label class="ops-check"><input v-model="settings.auto_replies" type="checkbox"/>Разрешить автоматическую отправку ответов на обычные обращения</label><label>Максимум автоответов в сутки<input v-model.number="settings.auto_reply_daily_limit" type="number" min="0" max="100"/></label><p class="field-note">Жалобы, вопросы оплаты, персональных данных и ответы с недостаточными сведениями остаются на ручное согласование.</p>
   <h3>Свои навыки AI</h3><p class="field-note">Добавьте инструкцию нового типа маркетинговой задачи. Навык готовит внутренний материал и не получает права отправки или запуска команд.</p><div v-for="(s,i) in settings.skills||[]" :key="s.id" class="ops-row"><b>{{s.name}}</b><button type="button" class="button secondary" @click="settings.skills.splice(i,1)">Убрать из формы</button></div><label>ID навыка<input v-model="newSkill.id" placeholder="Например: employer_brand"/></label><label>Название навыка<input v-model="newSkill.name"/></label><label>Инструкция<textarea v-model="newSkill.instruction" rows="3" maxlength="6000"></textarea></label><button type="button" class="button secondary" @click="addSkill"><Plus :size="15"/>Добавить навык в форму</button><button class="button primary" :disabled="busy||!canManage">Сохранить правила компании</button>
  </form>
  <section v-if="section==='connections'" class="panel ops-form"><h3>Подключения площадок</h3><p class="field-note">VK и MAX подготовлены без токенов. Интеграции не тестировались. Перед реальным использованием потребуются токен, нужные права и проверка в тестовом канале.</p><form v-for="platform in ['vk','max']" :key="platform" class="ops-card ops-form" @submit.prevent="saveConnection(platform)"><h3>{{platform==='vk'?'ВКонтакте':'MAX'}}</h3><p>{{connections[platform].token_set?'Токен сохранён':'Токен не подключён'}} · {{connections[platform].verified?'Есть подтверждённый ответ площадки':'Подключение не проверено'}}</p><label>{{platform==='vk'?'ID сообщества':'ID канала'}}<input v-model="connections[platform].target" inputmode="numeric"/></label><label>Токен<input v-model="connections[platform].token" type="password" autocomplete="new-password" :placeholder="connections[platform].token_set?'Сохранён; оставьте пустым для сохранения':'Добавить позже'"/></label><label class="ops-check"><input v-model="connections[platform].enabled" type="checkbox"/>Включить подключение</label><label class="ops-check"><input v-model="connections[platform].monitor" type="checkbox"/>Собирать доступную статистику и комментарии</label><p v-if="connections[platform].last_error" class="error-banner">{{connections[platform].last_error}}</p><div class="ops-actions"><button class="button secondary" :disabled="busy||!canManage">Сохранить {{platform.toUpperCase()}}</button><button v-if="connections[platform].token_set" type="button" class="button danger-text" :disabled="busy||!canManage" @click="revokeConnection(platform)">Отключить и удалить токен</button></div></form></section>
 </template>
</div>
</template>

<style scoped>
