:520px}.ops-table-wrap th,.ops-table-wrap td{padding:13px 10px;border-bottom:1px solid #e0e7e8;text-align:left;line-height:1.6}.ops-table-wrap th{color:#6b838b}.ops-notice{padding:15px 18px;border-radius:12px;background:#e8f4ef;color:#285f4d;font-size:13px;line-height:1.6}.ops-quota{display:grid;gap:12px;padding:18px;background:#f2f6f6;border-radius:12px}.ops-quota meter{width:100%;height:18px;accent-color:#196c7f}.ops-form .button{justify-self:start}.ops-form p{line-height:1.65}.ops-form details summary{cursor:pointer;font-size:12px;color:#196c7f}@media(max-width:900px){.ops-columns{grid-template-columns:1fr}}@media(max-width:620px){.ops-grid{grid-template-columns:1fr}.ops-card{padding:14px}.ops-actions{align-items:stretch}.ops-actions .button{width:100%;justify-content:center}.ops-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.ops-row{align-items:flex-start}.ops-row select{width:100%}}
</style>
